ALTER TABLE "user".promo ADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT TRUE;

ALTER TABLE "user".promo RENAME COLUMN from_date TO valid_from;
ALTER TABLE "user".promo RENAME COLUMN to_date TO valid_to;

ALTER TABLE "user".promo DROP COLUMN IF EXISTS discount_type;
